(* [comment removed for export] *)
Definition x1win (lo SPA DT mtl W : Z) (iv : Z * Z) : Prop :=
  fst iv <= snd iv /\
  ((lo <= fst iv /\ snd iv <= SPA) \/ (SPA + 8 <= fst iv /\ snd iv <= SPA + 80) \/ (SPA + 104 <= fst iv /\ snd iv <= SPA + 312)
   \/ (DT <= fst iv /\ snd iv <= DT + DTABLE_BYTES mtl) \/ (W <= fst iv /\ snd iv <= W + 8704)).

Section Asm.
Variable AI : AMallocIface.
Notation CI := (aci AI).
Variable fflag : alayout -> Z -> Z -> Z.
Variable rng_fs : alayout -> footprint -> Prop.
Hypothesis FFLAG : fake_flag_law AI fflag.
Hypothesis FREL : fake_release_law AI fflag.
Hypothesis SM0K : stack_malloc_0k_stmt AI fflag rng_fs 0.
Hypothesis RSK : huf_rstats_stmtA AI rng_fs 1.
Notation FB0 F := (mkABlock (ABFake 0) F 64).
Local Notation x1_open := (AF_huf_x1t_top.x1_open AI fflag rng_fs SM0K).
Local Notation x1_close := (AF_huf_x1t_top.x1_close AI fflag FFLAG FREL).
Local Notation PAGx := (AF_huf_x1t_top.PAGx AI).

Section After.
Variables (L : alayout) (RNG : footprint) (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
          (m : amem) (st : astate) (LB : list ablock) (SPV DT W S mtl lo FF : Z) (pdt pw : aptr) (src : list Z).
Notation SPA := (SPAx SPV).
Notation POST := (huf_rdt_postA AI huf_dt_okA L RNG ra (Z_to_bv 64 SPV) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB
                    DT W mtl lo m).
Hypothesis LBH : forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b).
Hypothesis HMTL : 1 <= mtl <= 12.
Hypothesis HDT : In (HB pdt DT (DTABLE_BYTES mtl)) LB.
Hypothesis HWB : In (HB pw W 8704) LB.
Hypothesis F64 : FF mod 64 = 0.
Hypothesis FH : ablk FF (FF + 64).
Hypothesis FC : FF + 64 <= ATOP.
Hypothesis RFF : rng RNG FF 64.
Hypothesis RSFF : rng RNG (shad FF) 8.
Hypothesis FFD : forall b, In b LB -> FF + 64 <= ab_addr b \/ ab_addr b + ab_size b <= FF.
Hypothesis BOT : ATOP + 4096 <= lo.
Hypothesis LO : lo <= SPV - HUF_RDT_STACK_A2.
Hypothesis SPT : SPV + 16 < al_top L.
Hypothesis SP16 : SPV mod 16 = 0.
Hypothesis RSTK : rng RNG lo (al_top L - lo).
Hypothesis RI : rng_aimg RNG.
Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.

(* [comment removed for export] *)
Definition x1_after (m4 : amem) : Prop :=
  AHEAP AI L RNG st (FB0 FF :: LB) m4 /\ magree asegs (PAGx LB SPV DT mtl W) m m4 /\ mem_inv asegs m4
  /\ rw_cells asegs m4 (Z.shiftr FF 3 + 2147450880) FDSH
  /\ (exists j0, rw_cells asegs m4 FF [C8 j0]) /\ rw_cells asegs m4 (FF + 56) [C8 (Z_to_bv 64 (fflag L 0 FF))]
